//! Deterministic code generation from `AppStruct` IR.

use appstruct_ir::{AppIr, FieldIr, FieldTypeIr, to_canonical_json};
use proc_macro2::{Ident, Span, TokenStream};
use quote::quote;
use std::error::Error;
use std::fmt;
use std::path::PathBuf;
use syn::LitStr;

/// A generated file planned in memory before any filesystem write.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Artifact {
    pub relative_path: PathBuf,
    pub content: Vec<u8>,
    pub executable: bool,
    pub kind: ArtifactKind,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ArtifactKind {
    CanonicalIr,
    RustManifest,
    RustSource,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct CodegenError {
    message: String,
}

impl fmt::Display for CodegenError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.message.fmt(formatter)
    }
}

impl Error for CodegenError {}

/// Plan the minimal M0 Rust artifact and its canonical input IR.
///
/// # Errors
///
/// Returns an error if an IR identifier is not valid Rust or serialization unexpectedly fails.
pub fn plan(ir: &AppIr) -> Result<Vec<Artifact>, CodegenError> {
    let ir_json = to_canonical_json(ir).map_err(|error| CodegenError {
        message: format!("failed to serialize canonical IR: {error}"),
    })?;
    let rust_source = generate_rust(ir)?;
    let cargo_manifest = concat!(
        "[package]\n",
        "name = \"appstruct-generated-backend\"\n",
        "version = \"0.0.0\"\n",
        "edition = \"2024\"\n",
        "rust-version = \"1.98\"\n\n",
        "[lib]\n",
        "path = \"src/lib.rs\"\n",
    );

    Ok(vec![
        Artifact {
            relative_path: PathBuf::from("ir/app-ir.json"),
            content: ir_json.into_bytes(),
            executable: false,
            kind: ArtifactKind::CanonicalIr,
        },
        Artifact {
            relative_path: PathBuf::from("backend/Cargo.toml"),
            content: cargo_manifest.as_bytes().to_vec(),
            executable: false,
            kind: ArtifactKind::RustManifest,
        },
        Artifact {
            relative_path: PathBuf::from("backend/src/lib.rs"),
            content: rust_source.into_bytes(),
            executable: false,
            kind: ArtifactKind::RustSource,
        },
    ])
}

fn generate_rust(ir: &AppIr) -> Result<String, CodegenError> {
    let app_name = LitStr::new(&ir.app.name, Span::call_site());
    let mut entity_tokens = Vec::with_capacity(ir.entities.len());
    for entity in &ir.entities {
        let entity_name = parse_ident(&entity.rust_name)?;
        let fields = entity
            .fields
            .iter()
            .map(field_tokens)
            .collect::<Result<Vec<_>, _>>()?;
        entity_tokens.push(quote! {
            #[derive(Clone, Debug, PartialEq)]
            pub struct #entity_name {
                #(#fields,)*
            }
        });
    }

    let tokens = quote! {
        pub const APP_NAME: &str = #app_name;
        pub const IR_VERSION: u32 = 1;

        #(#entity_tokens)*
    };
    let syntax = syn::parse2(tokens).map_err(|error| CodegenError {
        message: format!("generated Rust did not parse: {error}"),
    })?;
    let formatted = prettyplease::unparse(&syntax);
    Ok(format!(
        "// @generated by AppStruct. Do not edit manually.\n\n{formatted}"
    ))
}

fn field_tokens(field: &FieldIr) -> Result<TokenStream, CodegenError> {
    let name = parse_ident(&field.rust_name)?;
    let base_type = rust_type(&field.ty);
    let field_type = if field.nullable {
        quote! { Option<#base_type> }
    } else {
        base_type
    };
    Ok(quote! { pub #name: #field_type })
}

fn rust_type(field_type: &FieldTypeIr) -> TokenStream {
    match field_type {
        FieldTypeIr::Integer => quote! { i32 },
        FieldTypeIr::Bigint => quote! { i64 },
        FieldTypeIr::Boolean => quote! { bool },
        FieldTypeIr::Uuid
        | FieldTypeIr::String
        | FieldTypeIr::Text
        | FieldTypeIr::Decimal
        | FieldTypeIr::Date
        | FieldTypeIr::Datetime
        | FieldTypeIr::Json
        | FieldTypeIr::Enum { .. }
        | FieldTypeIr::Relation { .. } => quote! { String },
    }
}

fn parse_ident(value: &str) -> Result<Ident, CodegenError> {
    syn::parse_str(value).map_err(|error| CodegenError {
        message: format!("`{value}` is not a valid Rust identifier: {error}"),
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use appstruct_ir::{
        AccessRuleIr, AppMeta, AuthIr, ConcurrencyIr, CrudAccessIr, DatabaseDevMode, DatabaseIr,
        DatabaseProvider, EntityId, EntityIr, EntityViewsIr, FieldCapabilities, FieldId, HooksIr,
        IR_VERSION, ValidationIr,
    };

    #[test]
    fn generated_rust_parses() {
        let public_access = || CrudAccessIr {
            list: AccessRuleIr::Public,
            read: AccessRuleIr::Public,
            create: AccessRuleIr::Public,
            update: AccessRuleIr::Public,
            delete: AccessRuleIr::Public,
        };
        let entity_id = EntityId("app::Project".to_owned());
        let ir = AppIr {
            ir_version: IR_VERSION,
            app: AppMeta {
                name: "project-hub".to_owned(),
            },
            database: DatabaseIr {
                provider: DatabaseProvider::Postgres,
                dev_mode: DatabaseDevMode::Managed,
            },
            auth: AuthIr { enabled: false },
            enums: vec![],
            value_objects: vec![],
            entities: vec![EntityIr {
                id: entity_id.clone(),
                rust_name: "Project".to_owned(),
                api_name: "Project".to_owned(),
                label: "Project".to_owned(),
                table_name: "projects".to_owned(),
                fields: vec![FieldIr {
                    id: FieldId("app::Project.name".to_owned()),
                    entity: entity_id,
                    rust_name: "name".to_owned(),
                    api_name: "name".to_owned(),
                    column_name: "name".to_owned(),
                    ty: FieldTypeIr::String,
                    nullable: false,
                    primary_key: false,
                    generated: None,
                    default: None,
                    validation: ValidationIr::default(),
                    capabilities: FieldCapabilities {
                        searchable: true,
                        filterable: false,
                        sortable: false,
                    },
                }],
                access: public_access(),
                views: EntityViewsIr::default(),
                hooks: HooksIr::default(),
                concurrency: ConcurrencyIr { enabled: false },
            }],
            relations: vec![],
            commands: vec![],
            queries: vec![],
            pages: vec![],
            modules: vec![],
        };

        let artifacts = plan(&ir).unwrap();
        let source = artifacts
            .iter()
            .find(|artifact| artifact.kind == ArtifactKind::RustSource)
            .unwrap();
        syn::parse_file(std::str::from_utf8(&source.content).unwrap()).unwrap();
    }
}
